contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking arbitrary callee and data
    function run(address callee, bytes calldata data) public payable {
        require(true);
        // observe balance before
        uint balBefore = address(c).balance;

        // Perform the call and record whether it reverted
        bool reverted;
        bool successReturn;
        // We must attempt the call to c.forward and catch revert
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            successReturn = false;
        } else {
            reverted = false;
            // If forward returned (didn't revert), then the internal callee.call must have returned true due to require(_s)
            // We express that by setting successReturn = true in this branch
            successReturn = true;
        }

        uint balAfter = address(c).balance;

        // General rule: either reverted==true and then we don't assert anything about callee, or if it didn't revert
        // then C's balance is unchanged and the internal external call must have returned true (so successReturn==true).
        // Encode as: (!reverted) implies (balAfter == balBefore && successReturn)
        assert(reverted || (balAfter == balBefore && successReturn));
    }

    receive() external payable {}
}

